    var mt="Stock transfer "+ml[0].from.name+" to "+ml[0].to.name+", "+dayLabel(0)+"\n"+ml.map(function(m){return m.r.it.name+": "+n0(m.qty)+" "+m.r.it.uom.toLowerCase()+(m.qty===1?"":"s")}).join("\n");
