/* ---------- create a draft Purchase Order in ERPNext from the ticked lines of one supplier ---------- */
function poDocs(lines){
  var P=PO_DEFAULTS,today=new Date(dubaiNow()),groups={};
  lines.forEach(function(l){var sub=l.r.it.g==="P"?P.subPlants:P.subFlowers;(groups[sub]=groups[sub]||[]).push(l)});
  return Object.keys(groups).map(function(sub){var ls=groups[sub],first=null;
    var items=ls.map(function(l){var dd=new Date(today);dd.setUTCDate(dd.getUTCDate()+Math.max(0,l.r.lead));var req=dstr(dd.getTime());if(!first||req<first)first=req;
      return{item_code:l.code,qty:l.units,uom:l.pt.uom,conversion_factor:l.pt.cf,rate:l.pt.rate,schedule_date:req,warehouse:P.warehouse,cost_center:P.costCenter}});
    return{docstatus:0,naming_series:P.series,supplier:ls[0].sup,transaction_date:dstr(today.getTime()),schedule_date:first,company:P.company,custom_category:P.category,custom_subcategory:sub,cost_center:P.costCenter,currency:P.currency,conversion_rate:1,buying_price_list:P.priceList,set_warehouse:P.warehouse,taxes_and_charges:P.tax,taxes:[P.taxRow],items:items}});
}
