  var lines=orderLines.filter(function(l){return(l.sup||"")===sid&&l.day===day&&l.on&&l.qty>0});
  if(!lines.length){toast("Tick at least one line for this supplier");return}
  var total=0;lines.forEach(function(l){total+=l.val});
  if(btn.dataset.armed!=="1"){btn.dataset.armed="1";btn.textContent="Confirm: "+lines.length+" line"+(lines.length===1?"":"s")+", "+aed(total);setTimeout(function(){if(btn.isConnected&&btn.dataset.armed==="1"){btn.dataset.armed="";btn.textContent="Create draft PO"}},6000);return}
